SELECT jsonb_build_object('relations',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'relation',to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid'],
'columns',(SELECT jsonb_agg(jsonb_build_object('attribute',to_jsonb(at),'type',format_type(at.atttypid,at.atttypmod),'default',(SELECT pg_get_expr(d.adbin,d.adrelid)FROM pg_attrdef d WHERE d.adrelid=at.attrelid AND d.adnum=at.attnum))ORDER BY at.attnum)FROM pg_attribute at WHERE at.attrelid=c.oid AND at.attnum>0),
'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(k)||jsonb_build_object('definition',pg_get_constraintdef(k.oid,true))ORDER BY k.oid),'[]'::jsonb)FROM pg_constraint k WHERE k.conrelid=c.oid),
'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('catalog',to_jsonb(i),'definition',pg_get_indexdef(i.indexrelid),'relation',to_jsonb(ix)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid'])ORDER BY i.indexrelid),'[]'::jsonb)FROM pg_index i JOIN pg_class ix ON ix.oid=i.indexrelid WHERE i.indrelid=c.oid AND ix.relname<>'accounting_cash_receipts_scope_time_keys'),
 'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object('definition',pg_get_triggerdef(t.oid))ORDER BY t.oid),'[]'::jsonb)FROM pg_trigger t WHERE t.tgrelid=c.oid),
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(pol)ORDER BY pol.oid),'[]'::jsonb)FROM pg_policy pol WHERE pol.polrelid=c.oid))ORDER BY c.oid DESC)FROM pg_class c WHERE c.oid IN('public.accounting_cash_source_work'::regclass,'public.accounting_cash_source_receipts'::regclass)),
'owners',(SELECT jsonb_agg(jsonb_build_object('definition',pg_get_functiondef(fp.oid),'metadata',to_jsonb(fp))ORDER BY fp.oid)FROM pg_proc fp WHERE fp.oid IN(SELECT (e->'metadata'->>'oid')::oid FROM jsonb_array_elements(expected->'owners')e)),
'collation',(SELECT to_jsonb(co)FROM pg_collation co WHERE co.oid=100),
'database',(SELECT to_jsonb(db)-ARRAY['oid','datacl','datdba','datname','datminmxid','datallowconn','datconnlimit','datfrozenxid','datistemplate','dattablespace','dathasloginevt']FROM pg_database db WHERE db.datname=current_database()))INTO actual;
